-- Activity points are generated by database triggers, not by an untrusted browser client.
create or replace function public.record_activity_from_poll()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.created_by is not null then
    insert into public.user_activity (user_id, poll_id, activity_type)
    values (new.created_by, new.id, 'poll_created');
  end if;
  return new;
end;
$$;
revoke all on function public.record_activity_from_poll() from public;
drop trigger if exists polls_record_activity on public.polls;
create trigger polls_record_activity
after insert on public.polls
for each row execute function public.record_activity_from_poll();

